// Generated by Symposium. Do not edit.
// This extension connects Pi events to `cargo-agents hook pi`.
import { spawn } from "node:child_process";
import { existsSync, readdirSync, readFileSync } from "node:fs";
import { homedir } from "node:os";
import { dirname, join } from "node:path";
import { stripFrontmatter, type ExtensionAPI, type ExtensionContext } from "@earendil-works/pi-coding-agent";

interface HookOutput {
  decision?: "allow" | "deny";
  additionalContext?: string;
  updatedInput?: Record<string, unknown>;
}

// Hook commands install tools on demand, including during tool events.
export const DEFAULT_HOOK_TIMEOUT_MS = 10 * 60_000;

export function runHook(
  event: string,
  payload: Record<string, unknown>,
  cwd: string,
  command = "cargo-agents",
  signal?: AbortSignal,
  timeout = DEFAULT_HOOK_TIMEOUT_MS,
): Promise<HookOutput> {
  return new Promise((resolve, reject) => {
    const fail = (reason: string) => reject(new Error(`Symposium ${event}: ${reason}`));
    if (signal?.aborted) {
      fail("aborted");
      return;
    }
    // Do not use a shell: prompts and tool inputs are untrusted text. Unix
    // children inherit this isolated group, including plugin/install commands.
    const child = spawn(command, ["hook", "pi", event], {
      cwd, windowsHide: true, detached: process.platform !== "win32",
      stdio: ["pipe", "pipe", "pipe"],
    });
    let failure: string | undefined;
    const stop = (reason: string) => {
      if (failure) return;
      failure = reason;
      // Signal once while we own the live leader. Never kill a recorded PID
      // later, after Node has reaped it and the OS could reuse it.
      if (child.pid && child.exitCode === null && child.signalCode === null) {
        try {
          if (process.platform === "win32") child.kill();
          else process.kill(-child.pid, "SIGKILL");
        } catch (error) {
          if ((error as NodeJS.ErrnoException).code !== "ESRCH") {
            failure += `; could not stop hook: ${error}`;
            child.kill();
          }
        }
      }
      child.stdin.destroy();
      child.stdout.destroy();
      child.stderr.destroy();
    };
    const abort = () => stop("aborted");
    signal?.addEventListener("abort", abort, { once: true });
    const timer = timeout > 0 ? setTimeout(() => stop(`timed out after ${timeout} ms`), timeout) : undefined;
    const stdout: Buffer[] = [];
    const stderr: Buffer[] = [];
    for (const [stream, chunks, name] of [
      [child.stdout, stdout, "stdout"], [child.stderr, stderr, "stderr"],
    ] as const) {
      let bytes = 0;
      stream.on("data", (chunk: Buffer) => {
        bytes += chunk.length;
        if (bytes > 1024 * 1024) stop(`${name} exceeded 1 MiB`);
        else chunks.push(chunk);
      });
    }
    child.on("error", error => { failure ??= error.message; });
    child.on("close", (code, exitSignal) => {
      clearTimeout(timer);
      signal?.removeEventListener("abort", abort);
      if (failure) return fail(failure);
      if (code !== 0) {
        return fail(Buffer.concat(stderr).toString().trim() || `exited with ${exitSignal ?? code}`);
      }
      try {
        const text = Buffer.concat(stdout).toString().trim();
        const output = text ? JSON.parse(text) : {};
        if (!output || typeof output !== "object" || Array.isArray(output)) {
          throw new Error("expected a hook output object");
        }
        resolve(output);
      } catch (error) {
        fail(`invalid hook output: ${error}`);
      }
    });
    child.stdin.on("error", () => {}); // Process exit reports early stdin closure.
    child.stdin.end(JSON.stringify(payload));
  });
}

// Explicit SKILL.md paths bypass Pi's gitignore-aware directory scan.
// Only include Symposium-managed skills. User skills keep Pi's normal rules.
export function managedSkillPaths(cwd: string, home = homedir()): string[] {
  const parents = new Set<string>([join(home, ".agents", "skills")]);
  for (let dir = cwd; ; dir = dirname(dir)) {
    parents.add(join(dir, ".agents", "skills"));
    if (existsSync(join(dir, ".git")) || dirname(dir) === dir) break;
  }
  const paths: string[] = [];
  for (const parent of parents) {
    if (!existsSync(parent)) continue;
    for (const entry of readdirSync(parent, { withFileTypes: true })) {
      if (!entry.isDirectory()) continue;
      const skill = join(parent, entry.name);
      if (existsSync(join(skill, ".symposium")) && existsSync(join(skill, "SKILL.md"))) {
        paths.push(join(skill, "SKILL.md"));
      }
    }
  }
  return paths.sort();
}

// Pi expands templates after `input`. Appending context to their arguments can
// discard it ($1-only/no-argument templates) or change default arguments. Expand
// a known file-backed template first, then attach context to that same input.
// This mirrors Pi 1.0's argument syntax; streaming tests compare against its
// actual expander. No private Pi imports are available to installed extensions.
function promptWithContext(text: string, context: string, pi: ExtensionAPI): string {
  const match = text.match(/^\/([^\s]+)(?:\s+([\s\S]*))?$/);
  const template = match && pi.getCommands().find(command =>
    command.source === "prompt" && command.name === match[1]);
  if (template) {
    const args: string[] = [];
    let current = "";
    let quote: string | undefined;
    for (const char of match[2] ?? "") {
      if (quote) {
        if (char === quote) quote = undefined;
        else current += char;
      } else if (char === '"' || char === "'") {
        quote = char;
      } else if (/\s/.test(char)) {
        if (current) args.push(current);
        current = "";
      } else current += char;
    }
    if (current) args.push(current);
    const body = stripFrontmatter(readFileSync(template.sourceInfo.path, "utf8"));
    text = body.replace(
      /\$\{(\d+|ARGUMENTS|@):-([^}]*)\}|\$\{@:(\d+)(?::(\d+))?\}|\$(ARGUMENTS|@|\d+)/g,
      (_match, fallbackTarget, fallback, start, length, simple) => {
        if (fallbackTarget) {
          const value = fallbackTarget === "@" || fallbackTarget === "ARGUMENTS"
            ? args.join(" ") : args[Number(fallbackTarget) - 1];
          return value || fallback;
        }
        if (start) {
          const offset = Math.max(0, Number(start) - 1);
          return args.slice(offset, length ? offset + Number(length) : undefined).join(" ");
        }
        return simple === "@" || simple === "ARGUMENTS"
          ? args.join(" ") : args[Number(simple) - 1] ?? "";
      },
    );
    // A template's expanded text is not another slash command.
    return `\n${text}\n\nSymposium context:\n${context}`;
  }
  // Pi's skill expander separates the skill name at a literal space, not a
  // newline. Preserve that separator even for /skill:name with no arguments.
  const separator = text.startsWith("/skill:") ? " \n\n" : "\n\n";
  return `${text}${separator}Symposium context:\n${context}`;
}

type HookDispatcher = (
  event: string,
  payload: Record<string, unknown>,
  cwd: string,
  signal?: AbortSignal,
) => Promise<HookOutput>;

export default function (
  pi: ExtensionAPI,
  dispatch: HookDispatcher = (event, payload, cwd, signal) =>
    runHook(event, payload, cwd, "cargo-agents", signal),
) {
  const pendingContext = new Map<string, string>();
  let warned = false;
  const warn = (ctx: ExtensionContext, event: string, error: unknown) => {
    if (ctx.signal?.aborted || warned) return;
    warned = true;
    const message = `Symposium ${event} hook failed: ${error instanceof Error ? error.message : String(error)}`;
    try {
      if (ctx.hasUI) {
        ctx.ui.notify(message, "warning");
        return;
      }
    } catch {
      // A notification failure must not block a tool either.
    }
    console.warn(message); // Keep warnings off Pi's protocol stdout.
  };
  const invoke = async (
    event: string,
    ctx: ExtensionContext,
    fields: Record<string, unknown> = {},
  ): Promise<HookOutput> => {
    try {
      return await dispatch(event, {
        cwd: ctx.cwd,
        session_id: ctx.sessionManager.getSessionId(),
        ...fields,
      }, ctx.cwd, ctx.signal);
    } catch (error) {
      warn(ctx, event, error);
      return {};
    }
  };
  const addContext = (output: HookOutput) => {
    if (output.additionalContext) {
      pi.sendMessage(
        { customType: "symposium", content: output.additionalContext, display: false },
        { deliverAs: "nextTurn" },
      );
    }
  };

  // Pi fires resources_discover after session_start, so the first prompt can
  // use the skills installed by the session-start auto-sync.
  pi.on("session_start", async (_event, ctx) => {
    pendingContext.clear();
    warned = false;
    if (!ctx.isProjectTrusted()) return;
    addContext(await invoke("session-start", ctx));
  });
  pi.on("resources_discover", (event, ctx) => ({
    skillPaths: ctx.isProjectTrusted() ? managedSkillPaths(event.cwd) : [],
  }));

  pi.on("input", async (event, ctx) => {
    if (!ctx.isProjectTrusted()) return;
    const output = await invoke("user-prompt-submit", ctx, { prompt: event.text });
    if (!output.additionalContext) return;
    if (!event.streamingBehavior) {
      addContext(output);
      return;
    }
    try {
      const text = promptWithContext(event.text, output.additionalContext, pi);
      return { action: "transform", text, images: event.images };
    } catch (error) {
      warn(ctx, "user-prompt-submit", error);
    }
  });

  pi.on("tool_call", async (event, ctx) => {
    pendingContext.delete(event.toolCallId);
    if (!ctx.isProjectTrusted()) return;
    try {
      const output = await invoke("pre-tool-use", ctx, {
        tool_name: event.toolName, tool_input: event.input,
      });
      if (output.decision === "deny") {
        return {
          block: true,
          reason: typeof output.additionalContext === "string" && output.additionalContext
            ? output.additionalContext : "Blocked by Symposium",
        };
      }
      if (output.updatedInput !== undefined) {
        if (!output.updatedInput || typeof output.updatedInput !== "object" || Array.isArray(output.updatedInput)) {
          throw new Error("Symposium updatedInput must be an object");
        }
        const input = event.input as Record<string, unknown>;
        for (const key of Object.keys(input)) delete input[key];
        Object.assign(input, output.updatedInput);
      }
      if (typeof output.additionalContext === "string" && output.additionalContext) {
        pendingContext.set(event.toolCallId, output.additionalContext);
      }
    } catch (error) {
      warn(ctx, "pre-tool-use", error);
    }
  });

  pi.on("tool_result", async (event, ctx) => {
    const before = pendingContext.get(event.toolCallId);
    pendingContext.delete(event.toolCallId);
    if (!ctx.isProjectTrusted()) return;
    const output = await invoke("post-tool-use", ctx, {
      tool_name: event.toolName,
      tool_input: event.input,
      tool_response: {
        content: event.content,
        details: event.details,
        structuredContent: event.structuredContent,
        isError: event.isError,
      },
    });
    const context = [before, output.additionalContext].filter(
      (text): text is string => typeof text === "string" && text.length > 0,
    );
    if (context.length) {
      return {
        content: [...event.content, ...context.map((text) => ({ type: "text" as const, text }))],
        structuredContent: event.structuredContent,
      };
    }
  });

  pi.on("agent_end", async (_event, ctx) => {
    pendingContext.clear();
    if (!ctx.isProjectTrusted()) return;
    // No triggerTurn: a Stop hook must not start another agent turn.
    addContext(await invoke("stop", ctx));
  });
  pi.on("session_shutdown", () => { pendingContext.clear(); });
}
